#!/usr/bin/env bun
/**
 * Capture fixtures/media/recorder_headerless.webm with the browser MediaRecorder API.
 *
 * This asset is intentionally browser-origin media: a single MediaRecorder WebM blob with VP8 video
 * and Opus audio. It must not be generated by ffmpeg, because the benchmark needs the container shape
 * real browsers produce for recording/capture paths.
 */

import { mkdirSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium } from 'playwright';

const __dirname = dirname(fileURLToPath(import.meta.url));
const root = resolve(__dirname, '..');
const outPath = resolve(root, 'fixtures/media/recorder_headerless.webm');

const browser = await chromium.launch({ headless: false });
try {
  const page = await browser.newPage();
  const bytes = await page.evaluate(async () => {
    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 240;
    document.body.append(canvas);

    const ctx = canvas.getContext('2d');
    if (!ctx) throw new Error('2d canvas context unavailable');

    const videoStream = canvas.captureStream(30);
    const audio = new AudioContext({ sampleRate: 48000 });
    const oscillator = audio.createOscillator();
    const gain = audio.createGain();
    const destination = audio.createMediaStreamDestination();
    oscillator.frequency.value = 440;
    gain.gain.value = 0.035;
    oscillator.connect(gain).connect(destination);
    oscillator.start();

    const stream = new MediaStream([
      ...videoStream.getVideoTracks(),
      ...destination.stream.getAudioTracks(),
    ]);
    const mimeCandidates = [
      'video/webm;codecs=vp8,opus',
      'video/webm;codecs=vp8',
      'video/webm',
    ];
    const mimeType = mimeCandidates.find((candidate) => MediaRecorder.isTypeSupported(candidate));
    if (!mimeType) throw new Error('no supported MediaRecorder WebM mime type');

    const chunks = [];
    const recorder = new MediaRecorder(stream, { mimeType });
    recorder.ondataavailable = (event) => {
      if (event.data.size) chunks.push(event.data);
    };

    let frame = 0;
    let raf = 0;
    const draw = () => {
      const t = frame / 30;
      ctx.fillStyle = '#101418';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#39a3ff';
      ctx.fillRect((frame * 5) % canvas.width, 64, 80, 80);
      ctx.fillStyle = '#f7c948';
      ctx.beginPath();
      ctx.arc(160 + Math.sin(t * 4) * 80, 150, 32, 0, Math.PI * 2);
      ctx.fill();
      ctx.fillStyle = '#ffffff';
      ctx.font = '20px sans-serif';
      ctx.fillText(`MediaRecorder ${frame}`, 18, 34);
      frame++;
      raf = requestAnimationFrame(draw);
    };
    draw();

    await new Promise((resolve, reject) => {
      recorder.onerror = () => reject(recorder.error ?? new Error('MediaRecorder failed'));
      recorder.onstop = resolve;
      recorder.start();
      setTimeout(() => recorder.stop(), 3100);
    });

    cancelAnimationFrame(raf);
    oscillator.stop();
    await audio.close();
    for (const track of stream.getTracks()) track.stop();

    const blob = new Blob(chunks, { type: mimeType });
    return Array.from(new Uint8Array(await blob.arrayBuffer()));
  });

  mkdirSync(dirname(outPath), { recursive: true });
  writeFileSync(outPath, Buffer.from(bytes));
  console.log(`wrote ${outPath} (${bytes.length} bytes)`);
} finally {
  await browser.close();
}
